/* Reference Z80 interpreter: one bus access or internal cycle at a time,
 * counted in T-states. The opcode switch is generated by z80_gen from the
 * instruction templates (z80.c). */
#include <string.h>

#include "z80_ops.h"

void z80_reset(Z80 *c) {
    void *bus = c->bus;
    memset(c, 0, sizeof *c);
    c->bus = bus;
    c->a = c->f = 0xFF;  /* AF and SP are $FFFF after reset, everything else 0 (Zilog's manual, "Reset") */
    c->sp = 0xFFFF;
}

void z80_step(Z80 *c) {
    c->qprev = c->q;
    c->q = 0;
    c->p = 0;
    c->ei = 0;
    if (c->halted) {  /* HALT: NOPs fetched at the byte after it, the PC stays */
        z80_m1(c);
        c->pc--;
        return;
    }
    uint8_t op = z80_m1(c);
again:
    switch (op) {
#include "z80_switch.inc"
    }
}

/* the R count and the acknowledge cycle (n T-states, no read) of an interrupt */
static void accept(Z80 *c, unsigned n) {
    c->halted = 0;
    c->r = (uint8_t)((c->r & 0x80) | ((c->r + 1) & 0x7F));
    c->tstates += n;
    z80_idle(c, c->pc, n);
}
static void push_pc(Z80 *c) {
    z80_wr(c, --c->sp, (uint8_t)(c->pc >> 8));
    z80_wr(c, --c->sp, (uint8_t)c->pc);
}

unsigned z80_nmi(Z80 *c) {
    uint64_t t0 = c->tstates;
    c->iff1 = 0;
    accept(c, 5);
    push_pc(c);
    c->pc = c->wz = 0x66;
    return (unsigned)(c->tstates - t0);
}

unsigned z80_interrupt(Z80 *c) {
    if (!c->iff1 || c->ei) return 0;
    uint64_t t0 = c->tstates;
    c->iff1 = c->iff2 = 0;
    if (c->p) c->f &= (uint8_t)~Z80_FLAG_PV;  /* NMOS: an interrupt right after LD A,I or LD A,R clears P/V */
    accept(c, 7);  /* two wait states for the acknowledge cycle */
    uint8_t data = z80_irq_ack(c);
    push_pc(c);
    if (c->im == 2) {
        uint16_t vec = (uint16_t)(c->i << 8 | data);
        uint16_t lo = rd(c, vec);
        c->pc = (uint16_t)(lo | rd(c, (uint16_t)(vec + 1)) << 8);
    } else if (c->im == 1) {
        c->pc = 0x38;
    } else {
        /* shortcut: IM 0 runs the byte as RST n; a device that puts a CALL or another instruction on the bus is not supported (nothing uses it) */
        c->pc = (uint16_t)(data & 0x38);
    }
    c->wz = c->pc;
    return (unsigned)(c->tstates - t0);
}
